                "A imunidade inata reconhece padrões e responde rapidamente; a adaptativa envolve linfócitos com receptores específicos e capacidade de memória. As duas respostas cooperam continuamente. A resposta imune combina barreiras, reconhecimento e mecanismos efetores que precisam ser regulados. Proteção depende da qualidade da resposta, do agente, da via de exposição e das condições do animal. Células apresentadoras conectam reconhecimento inicial e ativação linfocitária. Citocinas coordenam recrutamento e diferenciação; anticorpos e respostas celulares atuam por mecanismos distintos conforme o agente. Como o conceito de imunidade inata e adaptativa ajuda a interpretar o exemplo? A resposta deve ligar o conceito às condições da situação e justificar a conclusão. Em um mapa de resposta a uma infecção, o estudante diferencia barreira epitelial, fagocitose, apresentação de antígeno, expansão clonal e formação de memória."
