                "Recém-nascidos de diferentes espécies recebem proteção materna por vias distintas. A transferência de imunoglobulinas depende do tipo placentário e da importância relativa do colostro. A resposta imune combina barreiras, reconhecimento e mecanismos efetores que precisam ser regulados. Proteção depende da qualidade da resposta, do agente, da via de exposição e das condições do animal. Nos ungulados domésticos, a ingestão e absorção de componentes colostrais têm grande relevância. Quantidade, qualidade e oportunidade da transferência influenciam a proteção inicial e a susceptibilidade a infecções. Como o conceito de imunidade neonatal e transferência passiva ajuda a interpretar o exemplo? A resposta deve ligar o conceito às condições da situação e justificar a conclusão. Uma comparação entre bezerro e filhote canino organiza diferenças de transferência materna e destaca a avaliação integrada da proteção neonatal no acompanhamento veterinário."
