                "Farmacodinâmica relaciona concentração, alvo e efeito. Nos antimicrobianos, a resposta depende também do agente, do sítio de infecção e de mecanismos de resistência. A farmacologia veterinária interpreta como características do animal e do produto influenciam efeito e segurança. Variações entre espécies impedem extrapolações simples; o estudo aqui é conceitual, sem prescrição ou cálculo de doses. Alterações do alvo, inativação de compostos, efluxo e menor permeabilidade podem reduzir susceptibilidade. Pressão seletiva favorece microrganismos resistentes, com consequências para saúde animal, humana e ambiental. Como o conceito de farmacodinâmica e resistência antimicrobiana ajuda a interpretar o exemplo? A resposta deve ligar o conceito às condições da situação e justificar a conclusão. Um seminário confronta identificação do agente, teste de susceptibilidade e contexto clínico para explicar o uso responsável, sem converter o resultado em uma prescrição automática."
